WITH filtered AS (SELECT *, ROUND(discount_pct, 2) AS discount_pct_rounded, FLOOR(discount_pct) AS discount_pct_whole FROM promotions WHERE starts_on >= TO_DATE('2023-09-01') AND channel IS NOT NULL), cleaned AS (SELECT *, COALESCE(discount_pct_rounded, 0) AS discount_pct_rounded_filled, ROUND(discount_pct * 1.1, 2) AS discount_pct_adjusted, COALESCE(channel, 'OTHER') AS resolved_channel FROM filtered WHERE discount_pct_rounded BETWEEN 35 AND 39), with_window AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM cleaned a JOIN promotions pr ON a.channel = pr.channel AND a.ends_on >= pr.starts_on AND a.ends_on < pr.ends_on + INTERVAL '30' DAY), attributed AS (SELECT s.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_2 FROM with_window s LEFT JOIN promotions pr ON s.channel <=> pr.channel AND s.ends_on >= pr.starts_on AND s.ends_on < pr.ends_on + INTERVAL 30 DAYS), valid AS (SELECT *, CASE WHEN promotion_discount_pct >= 0.27 THEN 'High' WHEN promotion_discount_pct >= 0.16 THEN 'Medium' ELSE 'Low' END AS promotion_discount_pct_level FROM attributed WHERE promotion_promo_code = 'WELCOME5' AND starts_on >= DATE '2023-06-05') SELECT id, starts_on, ends_on, discount_pct, discount_pct_rounded, discount_pct_whole, discount_pct_rounded_filled, resolved_channel, promo_id FROM valid
